use std::{path::PathBuf, process::Command};
use crate::{ingest::cache, model::FetchedAudio};
pub fn validate_url(url: &str) -> Result<(), String> { let accepted = ["youtube.com/watch", "youtu.be/", "youtube.com/shorts/"]; if accepted.iter().any(|part| url.contains(part)) { Ok(()) } else { Err("Enter a supported YouTube watch, youtu.be, or shorts URL".into()) } }
pub fn command_arguments(url: &str, output: &PathBuf) -> Vec<String> { vec!["-f".into(), "bestaudio[ext=m4a]".into(), "--no-playlist".into(), "-o".into(), output.to_string_lossy().into_owned(), url.into()] }
pub fn fetch(url: &str) -> Result<FetchedAudio, String> { validate_url(url)?; let version = Command::new("yt-dlp").arg("--version").output().map_err(|_| "yt-dlp is not installed. Install yt-dlp and add it to PATH.".to_owned())?; if !version.status.success() { return Err("yt-dlp is unavailable. Install yt-dlp and add it to PATH.".into()); } let info = Command::new("yt-dlp").args(["--print", "%(id)s|%(title)s|%(duration)s", "--skip-download", url]).output().map_err(|error| format!("Could not inspect YouTube URL: {error}"))?; if !info.status.success() { return Err("yt-dlp could not retrieve metadata for this URL".into()); } let line = String::from_utf8(info.stdout).map_err(|_| "yt-dlp metadata was not UTF-8".to_owned())?; let mut fields = line.trim().splitn(3, '|'); let video_id = fields.next().filter(|value| !value.is_empty()).ok_or_else(|| "yt-dlp returned no video id".to_owned())?.to_owned(); let title = fields.next().unwrap_or("Untitled").to_owned(); let duration_sec = fields.next().unwrap_or("0").parse::<f64>().unwrap_or(0.0); if let Some(item) = cache::cached_audio(&video_id)? { return Ok(item); } let output = cache::cache_directory()?.join(format!("{video_id}.m4a")); let status = Command::new("yt-dlp").args(command_arguments(url, &output)).status().map_err(|error| format!("Could not start yt-dlp: {error}"))?; if !status.success() || !output.is_file() { return Err("This video has no supported m4a audio stream".into()); } let item = FetchedAudio { path: output.to_string_lossy().into_owned(), video_id, title, duration_sec }; cache::save_metadata(&item)?; Ok(item) }
